CREATE TABLE budgets(id text PRIMARY KEY,payload text NOT NULL,revision integer NOT NULL DEFAULT 1,updated_at text NOT NULL);
CREATE TABLE members(email text PRIMARY KEY,user_id text,role text NOT NULL CHECK(role IN ('owner','viewer')),created_at text NOT NULL);
CREATE UNIQUE INDEX one_owner ON members(role) WHERE role='owner';
CREATE TABLE activity(id text PRIMARY KEY,actor text NOT NULL,action text NOT NULL,created_at text NOT NULL);
CREATE TABLE budget_state(id text PRIMARY KEY,name text NOT NULL,source_label text NOT NULL,source_imported_at text NOT NULL,source_period text NOT NULL,notes text NOT NULL,revision integer NOT NULL,updated_at text NOT NULL,write_token text NOT NULL,creditor_work_enabled integer NOT NULL DEFAULT 0,debt_history_enabled integer NOT NULL DEFAULT 0);
CREATE TABLE budget_plans(id text PRIMARY KEY,household_id text NOT NULL REFERENCES budget_state(id),name text NOT NULL,month text);
CREATE TABLE budget_items(id text NOT NULL,plan_id text NOT NULL REFERENCES budget_plans(id),kind text NOT NULL,name text NOT NULL,amount_cents bigint NOT NULL,frame_cents bigint,status text,note text,position integer NOT NULL,priority integer,PRIMARY KEY(plan_id,kind,id));
CREATE TABLE categories(name text PRIMARY KEY);
CREATE TABLE transactions(id text PRIMARY KEY,household_id text NOT NULL REFERENCES budget_state(id),date text NOT NULL,description text NOT NULL,amount_cents bigint NOT NULL,kind text NOT NULL,category text NOT NULL REFERENCES categories(name),reviewed integer NOT NULL,source text NOT NULL,excluded integer NOT NULL,position integer NOT NULL);
CREATE INDEX transactions_month_idx ON transactions(household_id,date);
CREATE INDEX transactions_category_idx ON transactions(category);
CREATE TABLE debts(id text PRIMARY KEY,household_id text NOT NULL REFERENCES budget_state(id),name text NOT NULL,balance_cents bigint NOT NULL,original_cents bigint NOT NULL,rate double precision,monthly_cents bigint NOT NULL,type text NOT NULL,note text NOT NULL,balance_verified integer NOT NULL,position integer NOT NULL);
CREATE TABLE savings_goals(id text PRIMARY KEY,household_id text NOT NULL REFERENCES budget_state(id),name text NOT NULL,target_cents bigint NOT NULL,saved_cents bigint NOT NULL,monthly_cents bigint NOT NULL,position integer NOT NULL);
CREATE TABLE budget_backups(id text PRIMARY KEY,revision integer NOT NULL,created_at text NOT NULL,reason text NOT NULL,sha256 text NOT NULL);
CREATE TABLE backup_chunks(backup_id text NOT NULL REFERENCES budget_backups(id),position integer NOT NULL,payload text NOT NULL,PRIMARY KEY(backup_id,position));
CREATE TABLE creditor_cases(id text PRIMARY KEY,household_id text NOT NULL REFERENCES budget_state(id),name text NOT NULL,debt_id text NOT NULL,contact text NOT NULL,email text NOT NULL,phone text NOT NULL,reference text NOT NULL,contact_source text NOT NULL,notes text NOT NULL,archived integer NOT NULL,position integer NOT NULL);
CREATE TABLE creditor_activities(id text PRIMARY KEY,household_id text NOT NULL REFERENCES budget_state(id),case_id text NOT NULL REFERENCES creditor_cases(id),type text NOT NULL,status text NOT NULL,channel text NOT NULL,date text NOT NULL,next_date text NOT NULL,requested text NOT NULL,agreed text NOT NULL,confirmation text NOT NULL,period_from text NOT NULL,period_to text NOT NULL,notes text NOT NULL,position integer NOT NULL);
CREATE INDEX creditor_activity_followup_idx ON creditor_activities(case_id,next_date);
CREATE TABLE debt_checkpoints(household_id text NOT NULL REFERENCES budget_state(id),date text NOT NULL,balances text NOT NULL,PRIMARY KEY(household_id,date));
